static auto
compute_prim_geom_10_lk_electron_repulsion_2_piece10(CSimdMatrix &buffer, const size_t target,
                                                     const size_t kk, const size_t mk,
                                                     const size_t ncols,
                                                     const double alpha) -> void
{
    // NOTE: the factors are fixed by the pair of primitives, so they are formed
    // once rather than for every atom pair the pair reaches.

    const auto f_0 = 2.0 * alpha;

    auto *t_1609 = buffer.data(target + 1609);
    auto *t_1610 = buffer.data(target + 1610);
    auto *t_1611 = buffer.data(target + 1611);
    auto *t_1612 = buffer.data(target + 1612);
    auto *t_1613 = buffer.data(target + 1613);
    auto *t_1614 = buffer.data(target + 1614);
    auto *t_1615 = buffer.data(target + 1615);
    auto *t_1616 = buffer.data(target + 1616);
    auto *t_1617 = buffer.data(target + 1617);
    auto *t_1618 = buffer.data(target + 1618);
    auto *t_1619 = buffer.data(target + 1619);

    const auto *kk_1285 = buffer.data(kk + 1285);
    const auto *kk_1286 = buffer.data(kk + 1286);
    const auto *kk_1287 = buffer.data(kk + 1287);
    const auto *kk_1288 = buffer.data(kk + 1288);
    const auto *kk_1289 = buffer.data(kk + 1289);
    const auto *kk_1290 = buffer.data(kk + 1290);
    const auto *kk_1291 = buffer.data(kk + 1291);
    const auto *kk_1292 = buffer.data(kk + 1292);
    const auto *kk_1293 = buffer.data(kk + 1293);
    const auto *kk_1294 = buffer.data(kk + 1294);
    const auto *kk_1295 = buffer.data(kk + 1295);

    const auto *mk_1969 = buffer.data(mk + 1969);
    const auto *mk_1970 = buffer.data(mk + 1970);
    const auto *mk_1971 = buffer.data(mk + 1971);
    const auto *mk_1972 = buffer.data(mk + 1972);
    const auto *mk_1973 = buffer.data(mk + 1973);
    const auto *mk_1974 = buffer.data(mk + 1974);
    const auto *mk_1975 = buffer.data(mk + 1975);
    const auto *mk_1976 = buffer.data(mk + 1976);
    const auto *mk_1977 = buffer.data(mk + 1977);
    const auto *mk_1978 = buffer.data(mk + 1978);
    const auto *mk_1979 = buffer.data(mk + 1979);

#pragma omp simd aligned(t_1609, t_1610, t_1611, t_1612, t_1613, kk_1285, kk_1286, kk_1287, \
                         kk_1288, kk_1289, mk_1969, mk_1970, mk_1971, mk_1972, \
                         mk_1973 : simd::cache_line_size())
    for (size_t k = 0; k < ncols; k++)
    {
        t_1609[k] = -8.0 * kk_1285[k]
                    + f_0 * mk_1969[k];

        t_1610[k] = -8.0 * kk_1286[k]
                    + f_0 * mk_1970[k];

        t_1611[k] = -8.0 * kk_1287[k]
                    + f_0 * mk_1971[k];

        t_1612[k] = -8.0 * kk_1288[k]
                    + f_0 * mk_1972[k];

        t_1613[k] = -8.0 * kk_1289[k]
                    + f_0 * mk_1973[k];
    }

#pragma omp simd aligned(t_1614, t_1615, t_1616, t_1617, t_1618, kk_1290, kk_1291, kk_1292, \
                         kk_1293, kk_1294, mk_1974, mk_1975, mk_1976, mk_1977, \
                         mk_1978 : simd::cache_line_size())
    for (size_t k = 0; k < ncols; k++)
    {
        t_1614[k] = -8.0 * kk_1290[k]
                    + f_0 * mk_1974[k];

        t_1615[k] = -8.0 * kk_1291[k]
                    + f_0 * mk_1975[k];

        t_1616[k] = -8.0 * kk_1292[k]
                    + f_0 * mk_1976[k];

        t_1617[k] = -8.0 * kk_1293[k]
                    + f_0 * mk_1977[k];

        t_1618[k] = -8.0 * kk_1294[k]
                    + f_0 * mk_1978[k];
    }

#pragma omp simd aligned(t_1619, kk_1295, mk_1979 : simd::cache_line_size())
    for (size_t k = 0; k < ncols; k++)
    {
        t_1619[k] = -8.0 * kk_1295[k]
                    + f_0 * mk_1979[k];
    }
}

